    // Geometric functions (float vectors only; MSL has no scalar overloads). Evaluated the way
    // Apple GPUs evaluate them under precise math (bit-exact except for subnormal flushing):
    // dot is an fma chain in component order; length/normalize scale by an exact power of two.

    /// <summary>Dot product, evaluated as an fma chain in component order (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::dot")]
    public static float Dot(Float2 x, Float2 y) => MathF.FusedMultiplyAdd(x.Y, y.Y, x.X * y.X);

    /// <summary>Dot product, evaluated as an fma chain in component order (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::dot")]
    public static float Dot(Float3 x, Float3 y) => MathF.FusedMultiplyAdd(x.Z, y.Z, MathF.FusedMultiplyAdd(x.Y, y.Y, x.X * y.X));

    /// <summary>Dot product, evaluated as an fma chain in component order (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::dot")]
    public static float Dot(Float4 x, Float4 y) => MathF.FusedMultiplyAdd(x.W, y.W, MathF.FusedMultiplyAdd(x.Z, y.Z, MathF.FusedMultiplyAdd(x.Y, y.Y, x.X * y.X)));

    /// <summary>Euclidean length. Scales by an exact power of two first, so it neither overflows nor underflows (<c>length(0, 0, FLT_MAX) == FLT_MAX</c>).</summary>
    [MslIntrinsic("metal::length")]
    public static float Length(Float2 x)
    {
        float m = MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y));
        if (m == 0f || !float.IsFinite(m))
        {
            return Sqrt(Dot(x, x)); // 0, +inf or NaN
        }

        int e = MathF.ILogB(m);
        Float2 s = ScaleB(x, -e);
        return MathF.ScaleB(Sqrt(Dot(s, s)), e);
    }

    /// <summary>Euclidean length. Scales by an exact power of two first, so it neither overflows nor underflows (<c>length(0, 0, FLT_MAX) == FLT_MAX</c>).</summary>
    [MslIntrinsic("metal::length")]
    public static float Length(Float3 x)
    {
        float m = MathF.Max(MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y)), MathF.Abs(x.Z));
        if (m == 0f || !float.IsFinite(m))
        {
            return Sqrt(Dot(x, x)); // 0, +inf or NaN
        }

        int e = MathF.ILogB(m);
        Float3 s = ScaleB(x, -e);
        return MathF.ScaleB(Sqrt(Dot(s, s)), e);
    }

    /// <summary>Euclidean length. Scales by an exact power of two first, so it neither overflows nor underflows (<c>length(0, 0, FLT_MAX) == FLT_MAX</c>).</summary>
    [MslIntrinsic("metal::length")]
    public static float Length(Float4 x)
    {
        float m = MathF.Max(MathF.Max(MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y)), MathF.Abs(x.Z)), MathF.Abs(x.W));
        if (m == 0f || !float.IsFinite(m))
        {
            return Sqrt(Dot(x, x)); // 0, +inf or NaN
        }

        int e = MathF.ILogB(m);
        Float4 s = ScaleB(x, -e);
        return MathF.ScaleB(Sqrt(Dot(s, s)), e);
    }

    /// <summary><c>length(x - y)</c>.</summary>
    [MslIntrinsic("metal::distance")]
    public static float Distance(Float2 x, Float2 y) => Length(x - y);

    /// <summary><c>length(x - y)</c>.</summary>
    [MslIntrinsic("metal::distance")]
    public static float Distance(Float3 x, Float3 y) => Length(x - y);

    /// <summary><c>length(x - y)</c>.</summary>
    [MslIntrinsic("metal::distance")]
    public static float Distance(Float4 x, Float4 y) => Length(x - y);

    /// <summary>Unit vector in the direction of <paramref name="x"/>, scaled by an exact power of two first so it neither overflows nor underflows. A zero vector is returned unchanged (signed zeros kept, no NaN); any infinite or NaN component gives NaN in every component.</summary>
    [MslIntrinsic("metal::normalize")]
    public static Float2 Normalize(Float2 x)
    {
        float m = MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y));
        if (m == 0f)
        {
            return x; // zero vector -> itself, signed zeros kept (as on Apple GPUs)
        }

        if (!float.IsFinite(m))
        {
            return new Float2(float.NaN); // any infinity or NaN -> NaN (as on Apple GPUs)
        }

        Float2 s = ScaleB(x, -MathF.ILogB(m));
        return s * Rsqrt(Dot(s, s));
    }

    /// <summary>Unit vector in the direction of <paramref name="x"/>, scaled by an exact power of two first so it neither overflows nor underflows. A zero vector is returned unchanged (signed zeros kept, no NaN); any infinite or NaN component gives NaN in every component.</summary>
    [MslIntrinsic("metal::normalize")]
    public static Float3 Normalize(Float3 x)
    {
        float m = MathF.Max(MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y)), MathF.Abs(x.Z));
        if (m == 0f)
        {
            return x; // zero vector -> itself, signed zeros kept (as on Apple GPUs)
        }

        if (!float.IsFinite(m))
        {
            return new Float3(float.NaN); // any infinity or NaN -> NaN (as on Apple GPUs)
        }

        Float3 s = ScaleB(x, -MathF.ILogB(m));
        return s * Rsqrt(Dot(s, s));
    }

    /// <summary>Unit vector in the direction of <paramref name="x"/>, scaled by an exact power of two first so it neither overflows nor underflows. A zero vector is returned unchanged (signed zeros kept, no NaN); any infinite or NaN component gives NaN in every component.</summary>
    [MslIntrinsic("metal::normalize")]
    public static Float4 Normalize(Float4 x)
    {
        float m = MathF.Max(MathF.Max(MathF.Max(MathF.Abs(x.X), MathF.Abs(x.Y)), MathF.Abs(x.Z)), MathF.Abs(x.W));
        if (m == 0f)
        {
            return x; // zero vector -> itself, signed zeros kept (as on Apple GPUs)
        }

        if (!float.IsFinite(m))
        {
            return new Float4(float.NaN); // any infinity or NaN -> NaN (as on Apple GPUs)
        }

        Float4 s = ScaleB(x, -MathF.ILogB(m));
        return s * Rsqrt(Dot(s, s));
    }

    /// <summary>Reflection of <paramref name="i"/> about the normal <paramref name="n"/>: <c>i - 2 * dot(n, i) * n</c>, evaluated as <c>fma(-2 * dot(n, i), n, i)</c> (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::reflect")]
    public static Float2 Reflect(Float2 i, Float2 n)
    {
        float k = -2f * Dot(n, i);
        return new Float2(MathF.FusedMultiplyAdd(k, n.X, i.X), MathF.FusedMultiplyAdd(k, n.Y, i.Y));
    }

    /// <summary>Reflection of <paramref name="i"/> about the normal <paramref name="n"/>: <c>i - 2 * dot(n, i) * n</c>, evaluated as <c>fma(-2 * dot(n, i), n, i)</c> (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::reflect")]
    public static Float3 Reflect(Float3 i, Float3 n)
    {
        float k = -2f * Dot(n, i);
        return new Float3(MathF.FusedMultiplyAdd(k, n.X, i.X), MathF.FusedMultiplyAdd(k, n.Y, i.Y), MathF.FusedMultiplyAdd(k, n.Z, i.Z));
    }

    /// <summary>Reflection of <paramref name="i"/> about the normal <paramref name="n"/>: <c>i - 2 * dot(n, i) * n</c>, evaluated as <c>fma(-2 * dot(n, i), n, i)</c> (as on Apple GPUs).</summary>
    [MslIntrinsic("metal::reflect")]
    public static Float4 Reflect(Float4 i, Float4 n)
    {
        float k = -2f * Dot(n, i);
        return new Float4(MathF.FusedMultiplyAdd(k, n.X, i.X), MathF.FusedMultiplyAdd(k, n.Y, i.Y), MathF.FusedMultiplyAdd(k, n.Z, i.Z), MathF.FusedMultiplyAdd(k, n.W, i.W));
    }

    private static Float2 ScaleB(Float2 v, int e) => new Float2(MathF.ScaleB(v.X, e), MathF.ScaleB(v.Y, e));

    private static Float3 ScaleB(Float3 v, int e) => new Float3(MathF.ScaleB(v.X, e), MathF.ScaleB(v.Y, e), MathF.ScaleB(v.Z, e));

    private static Float4 ScaleB(Float4 v, int e) => new Float4(MathF.ScaleB(v.X, e), MathF.ScaleB(v.Y, e), MathF.ScaleB(v.Z, e), MathF.ScaleB(v.W, e));
}
